# Independent geometric oracle: split each unit square along its anti-diagonal.
# Each triangle has area 1/2; its color is the parity of the line families at
# its centroid. Integer thirds avoid floating-point comparisons on boundaries.
def cell_area_doubled(x, y):
    return sum(
        (x + (3*y + k)//6 + (3*x + 3*y + 2*k)//6) % 2 == 0
        for k in (1, 2)
    )

def brute(a, b, c, d):
    return sum(cell_area_doubled(x, y)
               for x in range(a, c) for y in range(b, d))

